await viewport.set({ width: 1280, height: 720 });
await tab.playwright.waitForTimeout(300);
let desktopMetrics = await tab.playwright.evaluate(() => {
  const metrics = document.querySelector('.decision-metrics');
  if (!metrics) return null;
  const style = getComputedStyle(metrics);
  const children = [...metrics.children].map(child => {
    const rect = child.getBoundingClientRect();
    return { top: Math.round(rect.top), left: Math.round(rect.left), width: Math.round(rect.width), height: Math.round(rect.height) };
  });
  return { columns: style.gridTemplateColumns, gap: style.gap, width: Math.round(metrics.getBoundingClientRect().width), children };
});
await viewport.set({ width: 768, height: 900 });
await tab.playwright.waitForTimeout(300);
let mobileMetrics = await tab.playwright.evaluate(() => {
  const metrics = document.querySelector('.decision-metrics');
  if (!metrics) return null;
  const style = getComputedStyle(metrics);
  const children = [...metrics.children].map(child => {
    const rect = child.getBoundingClientRect();
    return { top: Math.round(rect.top), left: Math.round(rect.left), width: Math.round(rect.width), height: Math.round(rect.height) };
  });
  return { columns: style.gridTemplateColumns, gap: style.gap, width: Math.round(metrics.getBoundingClientRect().width), children };
});
let logs = await tab.dev.logs({ levels: ['error', 'warn'], limit: 20 });
nodeRepl.write(JSON.stringify({ desktopMetrics, mobileMetrics, logs }, null, 2));

