padding:10px;border-right:1px solid var(--line)}.scout-facts>div:first-child{padding-left:0}.scout-facts>div:last-child{border:0}.scout-facts dt{font-size:10px}.scout-facts dd{font-size:12px;margin:2px 0 0}.gate-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px 18px}.gate-list>div{display:flex;align-items:flex-start;gap:8px;font-size:11px}.gate-list svg{margin-top:2px}.gate-list span{display:flex;flex-direction:column}.gate-list strong{font-weight:500;text-transform:capitalize}.gate-list small{color:var(--quiet);line-height:1.45}.gate-pass svg{color:var(--accent)}.gate-fail svg{color:#efb0a4}.scout-warning{display:flex;align-items:flex-start;gap:9px;border-left:2px solid var(--amber);padding:7px 12px;margin:14px 0;color:#d7c6aa;font-size:12px}.scout-warning p,.scout-warning ul{font-size:11px!important;margin:3px 0!important;color:var(--quiet)!important}.scout-approval{display:flex;align-items:center;justify-content:space-between;gap:18px;margin:16px 0}.scout-approval>div:last-child{display:flex;gap:8px}.scout-manifest{border-left:2px solid var(--accent);padding:12px 16px;margin:16px 0}.scout-manifest ul{color:var(--quiet);font-size:11px}.scout-review details>summary{cursor:pointer;color:#cad5d7;font-size:12px;padding:7px 0}
